async function importFile(file){if(!file)return;if(file.size>20*1024*1024){toast('文件不能超过 20 MB');return;}try{if(/\.json$/i.test(file.name)){const p=validateProject(JSON.parse(await file.text()),palette);++sourceRequest;++request;clearTimeout(debounce);worker?.terminate();worker=null;source=null;history=[];future=[];project=p;sourceName=file.name.replace(/\.json$/i,'');selected=countColors(p.grid)[0]?.code||palette[0].code;setView(false);$('source-name').textContent=sourceName;$('source-info').textContent='工程图纸 · 不包含原图';$('source-thumb').removeAttribute('src');$('sample-badge').hidden=true;for(const id of ['size','colors','outline','cleanup','background'])$(id).disabled=true;setBusy(false);update();toast('已恢复工程，可以继续精修。');}else{if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('请选择 JPG、PNG、WebP 图片或拾粒集工程 JSON。');const url=URL.createObjectURL(file);try{await setSource(url,file.name.replace(/\.[^.]+$/,''));if(originalUrl)URL.revokeObjectURL(originalUrl);originalUrl=url;}catch(e){URL.revokeObjectURL(url);throw e;}}}catch(e){toast(e.message||'文件读取失败');}}
