for(const [button,dialog] of [['help','help-dialog'],['algorithm-help','algorithm-dialog'],['about','algorithm-dialog']])$(button).onclick=()=>$(dialog).showModal();for(const d of document.querySelectorAll('dialog')){d.querySelector('.dialog-close').onclick=()=>d.close();d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}};}
function showPalette(){const query=$('palette-search').value.trim().toUpperCase();$('full-palette').replaceChildren();for(const p of palette.filter(p=>p.code.includes(query))){const b=document.createElement('button');b.setAttribute('aria-label',`选择 ${p.code}`);b.innerHTML=`<span class="swatch" style="background:${p.hex}"></span>${p.code}`;b.onclick=()=>{chooseColor(p.code);setTool('brush');setView(false);$('palette-dialog').close();};$('full-palette').append(b);}}
